1	package com.example.starter.radio.service;
2	
3	import java.time.Clock;
4	import java.util.List;
5	
6	import com.example.starter.radio.domain.ChangeOrderStatus;
7	import com.example.starter.radio.domain.DispensingStatus;
8	import com.example.starter.radio.model.ChangeCheck;
9	import com.example.starter.radio.model.ChangeOrder;
10	import com.example.starter.radio.model.Dispensing;
11	import com.example.starter.radio.model.DispensingVersion;
12	import com.example.starter.radio.model.MotherLiquor;
13	import com.example.starter.radio.model.Nuclide;
14	import com.example.starter.radio.model.Prescription;
15	import com.example.starter.radio.repository.ChangeOrderRepository;
16	import com.example.starter.radio.repository.DispensingRepository;
17	import com.example.starter.radio.repository.MotherLiquorRepository;
18	import com.example.starter.radio.repository.NuclideRepository;
19	import com.example.starter.radio.repository.PrescriptionRepository;
20	import org.springframework.dao.DuplicateKeyException;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	/**
25	 * 给药时刻变更（合成数据软件验证，不用于真实给药决策）。
26	 * 变更只引用“已计算但尚未发药”的分装、当前处方版本与新的 UTC 给药时刻（须晚于母液参考时刻）；
27	 * 按原合成核素半衰期与原母液快照重算目标活度，仍须满足原 ±10% 处方偏差与库存校验。
28	 * 提交只形成候选版本，不立即改有效分装；两名不同人员共同复核后才在同一事务内生效：
29	 * 替换给药时刻（新增处方版本）与计算版本、清除旧双人核对有效性，旧计算与签认全部保留。
30	 * 候选期间原版本仍可合法发药；批准与发药竞争仅一方先提交（先分装行后候选行统一加锁）。
31	 * 所有写操作幂等：同键同参重放首次冻结结果，同键异参 409，失败不占键。
32	 */
33	@Service
34	public class ChangeOrderService {
35	
36	    private final ChangeOrderRepository changeOrders;
37	    private final DispensingRepository dispensings;
38	    private final PrescriptionRepository prescriptions;
39	    private final MotherLiquorRepository motherLiquors;
40	    private final NuclideRepository nuclides;
41	    private final DecayService decay;
42	    private final Clock clock;
43	
44	    public ChangeOrderService(ChangeOrderRepository changeOrders,
45	                              DispensingRepository dispensings,
46	                              PrescriptionRepository prescriptions,
47	                              MotherLiquorRepository motherLiquors,
48	                              NuclideRepository nuclides,
49	                              DecayService decay,
50	                              Clock clock) {
51	        this.changeOrders = changeOrders;
52	        this.dispensings = dispensings;
53	        this.prescriptions = prescriptions;
54	        this.motherLiquors = motherLiquors;
55	        this.nuclides = nuclides;
56	        this.decay = decay;
57	        this.clock = clock;
58	    }
59	
60	    /**
61	     * 提交变更候选。
62	     *
63	     * @param requestId              幂等键
64	     * @param dispensingId           被变更分装
65	     * @param expectedVersion        客户端持有的分装版本（从 1 开始），与库内不一致 409
66	     * @param expectedPrescriptionVersion 客户端持有的当前处方版本号，与库内不一致 409
67	     * @param newAdministrationTimeEpoch 新的 UTC 给药时刻（epoch 秒），须晚于母液参考时刻
68	     */
69	    @Transactional
70	    public SubmitResult submit(String requestId, long dispensingId, int expectedVersion,
71	                               int expectedPrescriptionVersion, long newAdministrationTimeEpoch) {
72	        // 幂等重放：命中已冻结的提交结果，同参返回首次结果，异参 409；与业务校验同事务读取
73	        String fingerprint = Fingerprints.structured("SUBMIT", requestId, dispensingId, expectedVersion,
74	                expectedPrescriptionVersion, newAdministrationTimeEpoch);
75	        var existing = changeOrders.findBySubmitRequestId(requestId);
76	        if (existing.isPresent()) {
77	            return new SubmitResult(replayOrConflict(existing.get(), fingerprint), true);
78	        }
79	
80	        // 先锁分装行，串行化并发提交与发药/生效
81	        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(dispensingId)
82	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
83	        // 持锁后再次检查幂等键：并发同键提交在首个事务提交后于此重放首次冻结结果
84	        var raced = changeOrders.findBySubmitRequestId(requestId);
85	        if (raced.isPresent()) {
86	            return new SubmitResult(replayOrConflict(raced.get(), fingerprint), true);
87	        }
88	        if (dispensing.status() == DispensingStatus.DISPENSED) {
89	            throw new BusinessException("分装已发药，历史不可重开，禁止提交变更");
90	        }
91	        if (dispensing.status() == DispensingStatus.REJECTED) {
92	            throw new BusinessException("分装已拒绝，禁止提交变更");
93	        }
94	        if (expectedVersion != dispensing.versionNo()) {
95	            throw new ConflictException("分装版本已变化: expected=" + expectedVersion
96	                    + " actual=" + dispensing.versionNo());
97	        }
98	        Prescription current = prescriptions.findById(dispensing.prescriptionId()).orElseThrow();
99	        Prescription latest = prescriptions.findLatestByRoot(rootOf(current)).orElse(current);
100	        if (dispensing.prescriptionId() != latest.id()
101	                || expectedPrescriptionVersion != latest.versionNo()) {
102	            throw new ConflictException("处方版本已变化或引用非当前版本: expected=" + expectedPrescriptionVersion
103	                    + " current=" + latest.versionNo());
104	        }
105	        if (changeOrders.findActiveByDispensingForUpdate(dispensingId).isPresent()) {
106	            throw new BusinessException("该分装已存在待复核变更候选，须先生效或作废后再提交");
107	        }
108	
109	        MotherLiquor mother = motherLiquors.findById(dispensing.motherLiquorId())
110	                .orElseThrow(() -> new NotFoundException("母液批次不存在: " + dispensing.motherLiquorId()));
111	        Nuclide nuclide = nuclides.findById(mother.nuclideId()).orElseThrow();
112	        if (newAdministrationTimeEpoch <= mother.referenceTimeEpoch()) {
113	            throw new BusinessException("新给药时刻须晚于母液参考时刻");
114	        }
115	        if (newAdministrationTimeEpoch == latest.administrationTimeEpoch()) {
116	            throw new BusinessException("新给药时刻与当前给药时刻相同，无变更");
117	        }
118	
119	        // 按原合成核素半衰期与原母液快照（初始活度@参考时刻）重算目标活度
120	        double candidateActivity = decay.activityAt(mother.initialActivityBq(), mother.referenceTimeEpoch(),
121	                newAdministrationTimeEpoch, nuclide.halfLifeSeconds());
122	        double deviation = (candidateActivity - latest.prescribedActivityBq()) / latest.prescribedActivityBq();
123	        boolean withinTolerance = Math.abs(deviation) <= DispensingService.DISPENSE_TOLERANCE;
124	        // 库存校验：新时刻候选活度不得超过母液当前剩余活度推算至该时刻的可用活度。
125	        // 该校验只读快照，不扣减母液；且按原母液初始快照重算，成功重放不受随后剩余量变化影响。
126	        double availableAtNewTime = decay.activityAt(mother.remainingActivityBq(), mother.remainingTimeEpoch(),
127	                newAdministrationTimeEpoch, nuclide.halfLifeSeconds());
128	        boolean inventoryOk = candidateActivity <= availableAtNewTime + 1e-9 * Math.max(1.0, availableAtNewTime);
129	
130	        boolean legal = withinTolerance && inventoryOk;
131	        String calcStatus = legal ? "LEGAL" : "REJECTED";
132	        Double storedActivity = legal ? candidateActivity : null;
133	        ChangeOrderStatus orderStatus = legal ? ChangeOrderStatus.PENDING : ChangeOrderStatus.REJECTED;
134	        int candidateVersionNo = dispensing.versionNo() + 1;
135	
136	        long now = clock.instant().getEpochSecond();
137	        // 提交阶段不新增处方版本行：候选 pending 期间当前处方版本保持不变，原版本仍可合法发药。
138	        // 新处方版本在双人复核通过、生效的同一事务内创建（见 review）。
139	        try {
140	            long id = changeOrders.insert(requestId, fingerprint, dispensingId, expectedVersion,
141	                    latest.versionNo(), null, newAdministrationTimeEpoch, candidateVersionNo,
142	                    storedActivity, deviation, calcStatus, orderStatus, now);
143	            if (legal) {
144	                dispensings.markActiveChangeOrder(dispensingId, id, now);
145	            }
146	            ChangeOrder saved = changeOrders.findById(id).orElseThrow();
147	            return new SubmitResult(saved, false);
148	        } catch (DuplicateKeyException e) {
149	            return changeOrders.findBySubmitRequestId(requestId)
150	                    .map(d -> new SubmitResult(replayOrConflict(d, fingerprint), true))
151	                    .orElseThrow(() -> new IllegalStateException("变更候选写入冲突后读取失败", e));
152	        }
153	    }
154	
155	    /**
156	     * 双人复核。两名不同人员先后复核，单人重复复核 409；仅 PENDING 且计算合法候选可复核。
157	     * 第二名不同人员复核通过即同事务生效。
158	     */
159	    @Transactional
160	    public ChangeOrder review(long changeOrderId, String reviewer) {
161	        ChangeOrder read = changeOrders.findById(changeOrderId)
162	                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeOrderId));
163	        // 统一锁顺序：先分装行后候选行，与发药竞争路径一致，避免死锁
164	        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(read.dispensingId())
165	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + read.dispensingId()));
166	        ChangeOrder order = changeOrders.findByIdForUpdate(changeOrderId)
167	                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeOrderId));
168	        if (order.status() != ChangeOrderStatus.PENDING) {
169	            throw new BusinessException("变更单不处于待复核状态，禁止复核: " + order.status());
170	        }
171	        long now = clock.instant().getEpochSecond();
172	        if (order.firstReviewer() == null) {
173	            changeOrders.updateReviewer(changeOrderId, "first_reviewer", reviewer, now);
174	            changeOrders.insertCheck(changeOrderId, reviewer, 1, now);
175	            return changeOrders.findById(changeOrderId).orElseThrow();
176	        }
177	        if (order.firstReviewer().equals(reviewer)) {
178	            throw new ConflictException("变更复核须为两名不同人员，单人重复复核不生效: " + reviewer);
179	        }
180	        if (order.secondReviewer() != null) {
181	            throw new BusinessException("变更双人复核已完成，禁止重复复核");
182	        }
183	
184	        // 已持分装行锁；若原版本已抢先提交发药（status=DISPENSED），变更生效拒绝。
185	        if (dispensing.status() == DispensingStatus.DISPENSED) {
186	            throw new BusinessException("原版本已先行发药，变更生效拒绝");
187	        }
188	        if (dispensing.versionNo() + 1 != order.candidateVersionNo()
189	                || dispensing.activeChangeOrderId() == null
190	                || dispensing.activeChangeOrderId() != order.id()) {
191	            throw new BusinessException("分装版本与候选不一致，变更生效拒绝");
192	        }
193	
194	        // 同事务：创建新处方版本（旧版本保留）→ 候选置 APPROVED → 写入新计算版本证据
195	        // → 替换有效分装（时刻+活度+版本），清除旧双人核对有效性（first/second 置空、状态回落 CALCULATED）。
196	        // 旧版本行与旧签认行保留。
197	        Prescription base = prescriptions.findById(dispensing.prescriptionId()).orElseThrow();
198	        int newPrescriptionVersionNo = order.prescriptionVersion() + 1;
199	        String versionedCode = base.code() + "#v" + newPrescriptionVersionNo;
200	        long newPrescriptionId = prescriptions.insertVersion(versionedCode, rootOf(base), base.nuclideId(),
201	                base.prescribedActivityBq(), order.newAdministrationTimeEpoch(), newPrescriptionVersionNo, now);
202	        changeOrders.insertCheck(changeOrderId, reviewer, 2, now);
203	        changeOrders.markApproved(changeOrderId, reviewer, newPrescriptionId, now);
204	        dispensings.insertVersion(dispensing.id(), order.candidateVersionNo(), newPrescriptionId,
205	                order.newAdministrationTimeEpoch(), order.candidateActivityBq(), order.candidateDeviationRatio(),
206	                "LEGAL", changeOrderId, now);
207	        dispensings.applyNewVersion(dispensing.id(), newPrescriptionId, order.candidateActivityBq(),
208	                order.candidateDeviationRatio(), order.candidateVersionNo(), now);
209	        return changeOrders.findById(changeOrderId).orElseThrow();
210	    }
211	
212	    /**
213	     * 作废候选（幂等）。仅 PENDING 可作废；已生效/已失效/已拒绝不可作废。同键同参重放，异参 409。
214	     */
215	    @Transactional
216	    public ChangeOrder voidOrder(String requestId, long changeOrderId) {
217	        var byVoidKey = changeOrders.findByVoidRequestId(requestId);
218	        if (byVoidKey.isPresent()) {
219	            ChangeOrder o = byVoidKey.get();
220	            if (o.id() != changeOrderId) {
221	                throw new ConflictException("相同作废 requestId 引用不同变更单: " + requestId);
222	            }
223	            return o;
224	        }
225	
226	        ChangeOrder read = changeOrders.findById(changeOrderId)
227	                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeOrderId));
228	        // 统一锁顺序：先分装行后候选行
229	        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(read.dispensingId()).orElseThrow();
230	        ChangeOrder order = changeOrders.findByIdForUpdate(changeOrderId)
231	                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeOrderId));
232	        if (changeOrders.findBySubmitRequestId(requestId)
233	                .map(o -> o.id() != changeOrderId)
234	                .orElse(false)) {
235	            throw new ConflictException("requestId 已被用作其它变更单的提交键: " + requestId);
236	        }
237	        if (order.status() != ChangeOrderStatus.PENDING) {
238	            throw new BusinessException("变更单不处于待复核状态，禁止作废: " + order.status());
239	        }
240	        long now = clock.instant().getEpochSecond();
241	        changeOrders.markVoid(changeOrderId, requestId, now);
242	        if (dispensing.activeChangeOrderId() != null && dispensing.activeChangeOrderId() == order.id()) {
243	            dispensings.markActiveChangeOrder(dispensing.id(), null, now);
244	        }
245	        return changeOrders.findById(changeOrderId).orElseThrow();
246	    }
247	
248	    @Transactional(readOnly = true)
249	    public ChangeOrder getOrder(long changeOrderId) {
250	        return changeOrders.findById(changeOrderId)
251	                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeOrderId));
252	    }
253	
254	    /**
255	     * 版本计算证据查询：返回分装全部不可变计算版本（初始 + 历次变更）。
256	     */
257	    @Transactional(readOnly = true)
258	    public List<DispensingVersion> versions(long dispensingId) {
259	        if (dispensings.findDispensingById(dispensingId).isEmpty()) {
260	            throw new NotFoundException("分装批次不存在: " + dispensingId);
261	        }
262	        return dispensings.findVersions(dispensingId);
263	    }
264	
265	    /**
266	     * 变更单及其复核链证据查询。
267	     */
268	    @Transactional(readOnly = true)
269	    public ChangeEvidence evidence(long changeOrderId) {
270	        ChangeOrder order = getOrder(changeOrderId);
271	        return new ChangeEvidence(order, changeOrders.findChecks(changeOrderId));
272	    }
273	
274	    private long rootOf(Prescription p) {
275	        return p.rootPrescriptionId() == null ? p.id() : p.rootPrescriptionId();
276	    }
277	
278	    private ChangeOrder replayOrConflict(ChangeOrder existing, String fingerprint) {
279	        if (!existing.fingerprint().equals(fingerprint)) {
280	            throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复受理: " + existing.requestId());
281	        }
282	        return existing;
283	    }
284	
285	    /** 提交结果。replayed 为 true 表示命中幂等重放，未产生新候选与新版本行。 */
286	    public record SubmitResult(ChangeOrder order, boolean replayed) {
287	    }
288	
289	    /** 变更单证据：候选单与其双人复核链。 */
290	    public record ChangeEvidence(ChangeOrder order, List<ChangeCheck> reviews) {
291	    }
292	}
