18	import com.example.starter.radio.repository.NuclideRepository;
19	import com.example.starter.radio.repository.PrescriptionRepository;
20	import org.springframework.dao.DuplicateKeyException;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	/**
25	 * 分装计算、双人核对与发药勾稽。
26	 * 分装活度按衰变公式推算至给药时刻（UTC），与处方偏差恰 10% 合法、超过 10% 拒绝；
27	 * 发药与母液活度扣减在同一事务内完成；发药完成为终态，重复完成返回幂等成功。
28	 * 每次计算（含变更生效后的重算）在 dispensing_version 留存不可变版本证据，核对链按版本隔离。
29	 */
30	@Service
31	public class DispensingService {
32	
33	    /** 分装与处方活度偏差阈值：绝对值不超过 10%。 */
34	    public static final double DISPENSE_TOLERANCE = 0.10;
35	
36	    /** 勾稽平衡判定的相对容差（合成数据按 2 的幂衰变可精确复算，容差仅吸收浮点尾差）。 */
37	    private static final double BALANCE_RELATIVE_TOLERANCE = 1e-9;
38	
39	    private final DispensingRepository dispensings;
40	    private final MotherLiquorRepository motherLiquors;
41	    private final PrescriptionRepository prescriptions;
42	    private final CalibratorRepository calibrators;
43	    private final NuclideRepository nuclides;
44	    private final ChangeOrderRepository changeOrders;
45	    private final DecayService decay;
46	    private final Clock clock;
47	
48	    public DispensingService(DispensingRepository dispensings,
49	                             MotherLiquorRepository motherLiquors,
50	                             PrescriptionRepository prescriptions,
51	                             CalibratorRepository calibrators,
52	                             NuclideRepository nuclides,
53	                             ChangeOrderRepository changeOrders,
54	                             DecayService decay,
55	                             Clock clock) {
56	        this.dispensings = dispensings;
57	        this.motherLiquors = motherLiquors;
58	        this.prescriptions = prescriptions;
59	        this.calibrators = calibrators;
60	        this.nuclides = nuclides;
61	        this.changeOrders = changeOrders;
62	        this.decay = decay;
63	        this.clock = clock;
64	    }
65	
66	    /**
67	     * 分装计算：幂等；活度计须当日日检通过；母液与处方核素须一致。
68	     */
69	    @Transactional
70	    public Dispensing calculate(String requestId, long motherLiquorId, long prescriptionId, long calibratorId) {
71	        String fingerprint = Fingerprints.of(requestId, motherLiquorId, prescriptionId, calibratorId);
72	        var existing = dispensings.findDispensingByRequestId(requestId);
73	        if (existing.isPresent()) {
74	            return replayOrConflict(existing.get(), fingerprint);
75	        }
76	
77	        MotherLiquor mother = motherLiquors.findById(motherLiquorId)
78	                .orElseThrow(() -> new NotFoundException("母液批次不存在: " + motherLiquorId));
79	        Prescription prescription = prescriptions.findById(prescriptionId)
80	                .orElseThrow(() -> new NotFoundException("处方不存在: " + prescriptionId));
81	        calibrators.findCalibratorById(calibratorId)
82	                .orElseThrow(() -> new NotFoundException("活度计不存在: " + calibratorId));
83	        if (mother.nuclideId() != prescription.nuclideId()) {
84	            throw new BusinessException("母液与处方核素不一致，拒绝分装");
85	        }
86	        Nuclide nuclide = nuclides.findById(mother.nuclideId())
87	                .orElseThrow(() -> new IllegalStateException("核素表缺少记录: " + mother.nuclideId()));
88	
89	        LocalDate today = LocalDate.ofInstant(clock.instant(), ZoneOffset.UTC);
90	        var dailyCheck = calibrators.findDailyCheck(calibratorId, today);
91	        if (dailyCheck.isEmpty() || !dailyCheck.get().passed()) {
92	            throw new BusinessException("活度计当日日检未通过，禁止使用: calibratorId=" + calibratorId);
93	        }
94	
95	        double dispensedAtAdmin = decay.activityAt(mother.initialActivityBq(), mother.referenceTimeEpoch(),
96	                prescription.administrationTimeEpoch(), nuclide.halfLifeSeconds());
97	        double deviation = (dispensedAtAdmin - prescription.prescribedActivityBq())
98	                / prescription.prescribedActivityBq();
99	        boolean legal = Math.abs(deviation) <= DISPENSE_TOLERANCE;
100	
101	        long now = clock.instant().getEpochSecond();
102	        try {
103	            if (legal) {
104	                long id = dispensings.insertDispensing(requestId, fingerprint, motherLiquorId, prescriptionId,
105	                        calibratorId, dispensedAtAdmin, deviation, DispensingStatus.CALCULATED, now);
106	                dispensings.insertVersion(id, 1, prescriptionId, prescription.administrationTimeEpoch(),
107	                        dispensedAtAdmin, deviation, "LEGAL", null, now);
108	                return dispensings.findDispensingById(id).orElseThrow();
109	            }
110	            long id = dispensings.insertDispensing(requestId, fingerprint, motherLiquorId, prescriptionId,
111	                    calibratorId, null, deviation, DispensingStatus.REJECTED, now);
112	            dispensings.insertVersion(id, 1, prescriptionId, prescription.administrationTimeEpoch(),
113	                    null, deviation, "REJECTED", null, now);
114	            return dispensings.findDispensingById(id).orElseThrow();
115	        } catch (DuplicateKeyException e) {
116	            return dispensings.findDispensingByRequestId(requestId)
117	                    .map(d -> replayOrConflict(d, fingerprint))
118	                    .orElseThrow(() -> new IllegalStateException("分装幂等记录写入冲突后读取失败", e));
119	        }
120	    }
121	
122	    /**
123	     * 双人核对：两名不同人员先后核对，单人重复核对不生效（409）。
124	     */
125	    @Transactional
126	    public Dispensing check(long dispensingId, String checker) {
127	        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(dispensingId)
128	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
129	        if (dispensing.status() == DispensingStatus.REJECTED
130	                || dispensing.status() == DispensingStatus.DISPENSED) {
131	            throw new BusinessException("分装批次已处于终态，禁止核对: " + dispensing.status());
132	        }
133	        long now = clock.instant().getEpochSecond();
134	        if (dispensing.firstChecker() == null) {
135	            dispensings.updateChecker(dispensingId, "first_checker", checker, now);
136	            dispensings.insertCheck(dispensingId, dispensing.versionNo(), checker, 1, now);
137	            return dispensings.findDispensingById(dispensingId).orElseThrow();
138	        }
139	        if (dispensing.firstChecker().equals(checker)) {
140	            throw new ConflictException("双人核对须为两名不同人员，单人重复核对不生效: " + checker);
141	        }
142	        if (dispensing.secondChecker() != null) {
143	            throw new BusinessException("双人核对已完成，禁止重复核对");
144	        }
145	        dispensings.updateChecker(dispensingId, "second_checker", checker, now);
146	        dispensings.insertCheck(dispensingId, dispensing.versionNo(), checker, 2, now);
147	        dispensings.updateStatus(dispensingId, DispensingStatus.CHECKED, now);
148	        return dispensings.findDispensingById(dispensingId).orElseThrow();
149	    }
150	
151	    /**
152	     * 发药：勾稽“母液初始活度＝分装总量＋剩余活度＋衰变残量”，不等拒绝发药；
153	     * 发药与母液剩余活度扣减在同一事务内完成；发药完成为终态，重复完成返回幂等成功。
154	     */
155	    @Transactional
156	    public DispenseResult dispense(String requestId, long dispensingId,
157	                                   double remainingActivityBq, long measuredAtEpoch) {
158	        String fingerprint = Fingerprints.of(requestId, dispensingId, remainingActivityBq, measuredAtEpoch);
159	        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(dispensingId)
160	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
161	
162	        if (dispensing.status() == DispensingStatus.DISPENSED) {
163	            if (requestId.equals(dispensing.dispenseRequestId())) {
164	                if (!fingerprint.equals(dispensing.dispenseFingerprint())) {
165	                    throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复发药: " + requestId);
166	                }
167	                return new DispenseResult(dispensing, dispensings.findLedger(dispensingId).orElse(null), true);
168	            }
169	            // 终态重复完成：幂等成功，不重复扣减库存
170	            return new DispenseResult(dispensing, dispensings.findLedger(dispensingId).orElse(null), true);
171	        }
172	        if (dispensing.status() != DispensingStatus.CHECKED) {
173	            throw new BusinessException("分装批次未完成双人核对或已拒绝，禁止发药: " + dispensing.status());
174	        }
175	
176	        long now = clock.instant().getEpochSecond();
177	        // 原版本抢先发药：挂起候选即时失效（SUPERSEDED）。已先持有分装行锁再锁候选行，与变更生效同一锁顺序，
178	        // 因而“候选批准 vs 原版本发药”只有一方先提交。
179	        changeOrders.findActiveByDispensingForUpdate(dispensingId)
180	                .ifPresent(pending -> changeOrders.markSuperseded(pending.id(), now));
181	
182	        MotherLiquor mother = motherLiquors.findById(dispensing.motherLiquorId()).orElseThrow();
183	        Nuclide nuclide = nuclides.findById(mother.nuclideId()).orElseThrow();
184	        ReconciliationLedger ledger = reconcile(dispensing, mother, nuclide,
185	                remainingActivityBq, measuredAtEpoch);
186	        if (!ledger.balanced()) {
187	            throw new BusinessException(String.format(
188	                    "活度勾稽不平衡，拒绝发药: 初始=%.6f 分装总量=%.6f 剩余=%.6f 衰变残量=%.6f",
189	                    ledger.initialActivityBq(), ledger.dispensedTotalBq(),
190	                    ledger.remainingActivityBq(), ledger.decayResidualBq()));
191	        }
192	
193	        dispensings.insertLedger(ledger, now);
194	        dispensings.markDispensed(dispensingId, requestId, fingerprint, now);
195	        // 发药与母液活度扣减同事务：任一步失败整体回滚
196	        motherLiquors.updateRemaining(mother.id(), remainingActivityBq, measuredAtEpoch);
197	        Dispensing done = dispensings.findDispensingById(dispensingId).orElseThrow();
198	        return new DispenseResult(done, ledger, false);
199	    }
200	
201	    /**
202	     * 批次完成后迟到测量数据只记迟到事件，不改动业务状态。
203	     */
204	    @Transactional
205	    public String recordMeasurement(long dispensingId, String payload) {
206	        Dispensing dispensing = dispensings.findDispensingById(dispensingId)
207	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
208	        if (dispensing.status() != DispensingStatus.DISPENSED) {
209	            throw new BusinessException("分装批次未处于发药完成终态，测量数据应走正常流程: " + dispensing.status());
210	        }
211	        dispensings.insertLateEvent(dispensingId, "LATE_MEASUREMENT", payload,
212	                clock.instant().getEpochSecond());
213	        return "LATE_RECORDED";
214	    }
215	
216	    /**
217	     * 勾稽台账复算：按衰变公式由母液、分装与核对链原始数据重新计算。
218	     * 已发药批次按台账测量时刻复算；未发药批次按当前时刻试算。
219	     */
220	    @Transactional(readOnly = true)
221	    public ReconciliationLedger recompute(long dispensingId) {
222	        Dispensing dispensing = dispensings.findDispensingById(dispensingId)
223	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
224	        MotherLiquor mother = motherLiquors.findById(dispensing.motherLiquorId()).orElseThrow();
225	        Nuclide nuclide = nuclides.findById(mother.nuclideId()).orElseThrow();
226	        // 已落台账的批次按台账测量时刻复算，保证与台账逐项可比；否则按当前时刻试算
227	        long measuredAt = dispensings.findLedger(dispensingId)
228	                .map(ReconciliationLedger::measuredAtEpoch)
229	                .orElse(dispensing.dispensedAtEpoch() != null
230	                        ? dispensing.dispensedAtEpoch() : clock.instant().getEpochSecond());
231	        double remaining = decay.activityAt(mother.remainingActivityBq(), mother.remainingTimeEpoch(),
232	                measuredAt, nuclide.halfLifeSeconds());
233	        return reconcile(dispensing, mother, nuclide, remaining, measuredAt);
234	    }
235	
236	    /**
237	     * 勾稽：初始活度 = 分装总量 + 剩余活度 + 衰变残量（全部推算至 measuredAtEpoch）。
238	     */
239	    private ReconciliationLedger reconcile(Dispensing dispensing, MotherLiquor mother, Nuclide nuclide,
240	                                           double remainingActivityBq, long measuredAtEpoch) {
241	        long halfLife = nuclide.halfLifeSeconds();
242	        double decayResidual = decay.decayResidual(mother.initialActivityBq(),
243	                mother.referenceTimeEpoch(), measuredAtEpoch, halfLife);
244	        double dispensedTotal = 0.0;
245	        List<Dispensing> actives = dispensings.findActiveByMotherLiquor(mother.id());
246	        for (Dispensing active : actives) {
247	            if (active.dispensedActivityBq() == null) {
248	                continue;
249	            }
250	            Prescription p = prescriptions.findById(active.prescriptionId()).orElseThrow();
251	            dispensedTotal += decay.activityAt(active.dispensedActivityBq(),
252	                    p.administrationTimeEpoch(), measuredAtEpoch, halfLife);
253	        }
254	        double lhs = mother.initialActivityBq();
255	        double rhs = dispensedTotal + remainingActivityBq + decayResidual;
256	        boolean balanced = Math.abs(lhs - rhs) <= BALANCE_RELATIVE_TOLERANCE * Math.max(1.0, Math.abs(lhs));
257	        return new ReconciliationLedger(0L, dispensing.id(), lhs, dispensedTotal,
258	                remainingActivityBq, decayResidual, balanced, measuredAtEpoch);
259	    }
260	
261	    private Dispensing replayOrConflict(Dispensing existing, String fingerprint) {
262	        if (!existing.fingerprint().equals(fingerprint)) {
263	            throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复受理: " + existing.requestId());
264	        }
265	        return existing;
266	    }
267	
268	    /**
269	     * 发药结果。replayed 为 true 表示命中幂等重放或终态重复完成，未发生新的状态变更与扣减。
270	     */
271	    public record DispenseResult(Dispensing dispensing, ReconciliationLedger ledger, boolean replayed) {
272	    }
