35	class ChangeOrderServiceTest extends IntegrationTestBase {
36	
37	    private static final long ADMIN_1 = T0.getEpochSecond() + 3600L;
38	    private static final long NEW_ADMIN_LEGAL = T0.getEpochSecond() + 4500L;
39	    private static final long NEW_ADMIN_OVERSHOOT = T0.getEpochSecond() + 7200L;
40	
41	    @Autowired
42	    private ChangeOrderService changeOrders;
