54	    private MotherLiquorRepository motherLiquors;
55	
56	    @Autowired
57	    private DispensingRepository dispensingRepo;
58	
59	    @Autowired
60	    private ChangeOrderRepository changeOrderRepo;
61	
62	    @Test
63	    void submitCreatesCandidateWithoutChangingEffectiveDispensing() {
64	        Fixture f = newCalculatedFixture();
65	
66	        ChangeOrderService.SubmitResult result = changeOrders.submit(unique("CHG"), f.dispensingId,
67	                1, 1, NEW_ADMIN_LEGAL);
68	
69	        assertThat(result.replayed()).isFalse();
70	        ChangeOrder order = result.order();
71	        assertThat(order.status()).isEqualTo(ChangeOrderStatus.PENDING);
72	        assertThat(order.calcStatus()).isEqualTo("LEGAL");
73	        assertThat(order.candidateVersionNo()).isEqualTo(2);
74	        assertThat(order.candidateActivityBq()).isCloseTo(924.9860568, org.assertj.core.data.Offset.offset(1e-6));
75	        assertThat(order.candidateDeviationRatio()).isCloseTo(-0.0750139, org.assertj.core.data.Offset.offset(1e-6));
76	
77	        // 有效分装仍是旧版本：旧时刻/旧活度/版本 1，候选仅登记
78	        Dispensing effective = dispensingRepo.findDispensingById(f.dispensingId).orElseThrow();
79	        assertThat(effective.versionNo()).isEqualTo(1);
80	        assertThat(effective.dispensedActivityBq()).isEqualTo(1100.0);
81	        assertThat(effective.activeChangeOrderId()).isEqualTo(order.id());
82	    }
