84	    @Test
85	    void approvalSwapsVersionAndClearsOldChecksButKeepsEvidence() {
86	        Fixture f = newCheckedFixture();
87	        long orderId = submitLegal(f.dispensingId);
88	
89	        changeOrders.review(orderId, "carol");
90	        ChangeOrder approved = changeOrders.review(orderId, "dave");
91	
92	        assertThat(approved.status()).isEqualTo(ChangeOrderStatus.APPROVED);
93	        assertThat(approved.secondReviewer()).isEqualTo("dave");
94	
95	        Dispensing effective = dispensingRepo.findDispensingById(f.dispensingId).orElseThrow();
96	        // 同事务替换：新版本、新活度、状态回落待核对，旧双人核对有效性清除
97	        assertThat(effective.versionNo()).isEqualTo(2);
98	        assertThat(effective.status()).isEqualTo(DispensingStatus.CALCULATED);
99	        assertThat(effective.firstChecker()).isNull();
100	        assertThat(effective.secondChecker()).isNull();
101	        assertThat(effective.activeChangeOrderId()).isNull();
102	        assertThat(effective.dispensedActivityBq()).isCloseTo(924.9860568,
103	                org.assertj.core.data.Offset.offset(1e-6));
104	        // 旧签认行保留（v1 两条），但不再挂在有效分装字段上
105	        assertThat(dispensingRepo.findChecks(f.dispensingId)).hasSize(2);
106	        assertThat(dispensingRepo.findChecks(f.dispensingId).get(0).versionNo()).isEqualTo(1);
107	
108	        // 版本证据：v1 初始（1100，无变更单）+ v2 变更（924.986，挂本变更单）
109	        List<DispensingVersion> versions = changeOrders.versions(f.dispensingId);
110	        assertThat(versions).hasSize(2);
