    return jdbc.query(
            "SELECT id FROM dispensing_change_order WHERE dispensing_id = ? AND status = 'PENDING' FOR UPDATE"
                    + " ORDER BY id",
            (rs, i) -> rs.getLong("id"), dispensingId);
}

